            double hcH0_0_1__0_0_2__0_0_0__0_0_0 = (hcH0_0_2__0_0_1__0_0_0__0_0_0 + (AB_z * hcH0_0_1__0_0_1__0_0_0__0_0_0));
            // HRR a-: (0, 1, 0, 0) on U0
            // [Fock] eq 28, the HGP HRR on contracted values
            double hmH1_0_0__0_0_0__0_0_0__0_0_0 = U0C1_0_0__0_0_0;
            double hmH0_1_0__0_0_0__0_0_0__0_0_0 = U0C0_1_0__0_0_0;
            double hmH0_0_1__0_0_0__0_0_0__0_0_0 = U0C0_0_1__0_0_0;
            double hmH0_0_0__0_0_0__0_0_0__0_0_0 = U0C0_0_0__0_0_0;
            double hmH0_0_0__1_0_0__0_0_0__0_0_0 = (hmH1_0_0__0_0_0__0_0_0__0_0_0 + (AB_x * hmH0_0_0__0_0_0__0_0_0__0_0_0));
            double hmH0_0_0__0_1_0__0_0_0__0_0_0 = (hmH0_1_0__0_0_0__0_0_0__0_0_0 + (AB_y * hmH0_0_0__0_0_0__0_0_0__0_0_0));
            double hmH0_0_0__0_0_1__0_0_0__0_0_0 = (hmH0_0_1__0_0_0__0_0_0__0_0_0 + (AB_z * hmH0_0_0__0_0_0__0_0_0__0_0_0));
            // HRR c-: (1, 0, 0, 0) on U0
            // [Fock] eq 28, the HGP HRR on contracted values
            double hnH1_0_0__0_0_0__0_0_0__0_0_0 = U0C1_0_0__0_0_0;
            double hnH0_1_0__0_0_0__0_0_0__0_0_0 = U0C0_1_0__0_0_0;
            double hnH0_0_1__0_0_0__0_0_0__0_0_0 = U0C0_0_1__0_0_0;
            // the deposit: per ERI (ac|bd), W = M[a, b] M[c, d], and per axis gA += W
            // d/dA_k (ac|bd), gC += W d/dC_k (ac|bd)
            double dab_0_0 = M[((oa + 0) * n_ao + (ob + 0))];
            double dab_1_0 = M[((oa + 1) * n_ao + (ob + 0))];
            double dab_2_0 = M[((oa + 2) * n_ao + (ob + 0))];
            double dcd_0_0 = M[((oc + 0) * n_ao + (od + 0))];
            double dcd_1_0 = M[((oc + 1) * n_ao + (od + 0))];
            double dcd_2_0 = M[((oc + 2) * n_ao + (od + 0))];
            double w_0_0_0_0 = (dab_0_0 * dcd_0_0);
            gAx = (gAx + (w_0_0_0_0 * (haH2_0_0__1_0_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__1_0_0__0_0_0__0_0_0))));
            gCx = (gCx + (w_0_0_0_0 * (hcH1_0_0__2_0_0__0_0_0__0_0_0 - (1.0 * hnH1_0_0__0_0_0__0_0_0__0_0_0))));
            gAy = (gAy + (w_0_0_0_0 * haH1_1_0__1_0_0__0_0_0__0_0_0));
            gCy = (gCy + (w_0_0_0_0 * hcH1_0_0__1_1_0__0_0_0__0_0_0));
            gAz = (gAz + (w_0_0_0_0 * haH1_0_1__1_0_0__0_0_0__0_0_0));
            gCz = (gCz + (w_0_0_0_0 * hcH1_0_0__1_0_1__0_0_0__0_0_0));
            double w_0_1_0_0 = (dab_0_0 * dcd_1_0);
            gAx = (gAx + (w_0_1_0_0 * (haH2_0_0__0_1_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_1_0__0_0_0__0_0_0))));
            gCx = (gCx + (w_0_1_0_0 * hcH1_0_0__1_1_0__0_0_0__0_0_0));
            gAy = (gAy + (w_0_1_0_0 * haH1_1_0__0_1_0__0_0_0__0_0_0));
            gCy = (gCy + (w_0_1_0_0 * (hcH1_0_0__0_2_0__0_0_0__0_0_0 - (1.0 * hnH1_0_0__0_0_0__0_0_0__0_0_0))));
            gAz = (gAz + (w_0_1_0_0 * haH1_0_1__0_1_0__0_0_0__0_0_0));
            gCz = (gCz + (w_0_1_0_0 * hcH1_0_0__0_1_1__0_0_0__0_0_0));
            double w_0_2_0_0 = (dab_0_0 * dcd_2_0);
            gAx = (gAx + (w_0_2_0_0 * (haH2_0_0__0_0_1__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_0_1__0_0_0__0_0_0))));
            gCx = (gCx + (w_0_2_0_0 * hcH1_0_0__1_0_1__0_0_0__0_0_0));
            gAy = (gAy + (w_0_2_0_0 * haH1_1_0__0_0_1__0_0_0__0_0_0));
            gCy = (gCy + (w_0_2_0_0 * hcH1_0_0__0_1_1__0_0_0__0_0_0));
            gAz = (gAz + (w_0_2_0_0 * haH1_0_1__0_0_1__0_0_0__0_0_0));
            gCz = (gCz + (w_0_2_0_0 * (hcH1_0_0__0_0_2__0_0_0__0_0_0 - (1.0 * hnH1_0_0__0_0_0__0_0_0__0_0_0))));
            double w_1_0_0_0 = (dab_1_0 * dcd_0_0);
            gAx = (gAx + (w_1_0_0_0 * haH1_1_0__1_0_0__0_0_0__0_0_0));
            gCx = (gCx + (w_1_0_0_0 * (hcH0_1_0__2_0_0__0_0_0__0_0_0 - (1.0 * hnH0_1_0__0_0_0__0_0_0__0_0_0))));
            gAy = (gAy + (w_1_0_0_0 * (haH0_2_0__1_0_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__1_0_0__0_0_0__0_0_0))));
            gCy = (gCy + (w_1_0_0_0 * hcH0_1_0__1_1_0__0_0_0__0_0_0));
            gAz = (gAz + (w_1_0_0_0 * haH0_1_1__1_0_0__0_0_0__0_0_0));
            gCz = (gCz + (w_1_0_0_0 * hcH0_1_0__1_0_1__0_0_0__0_0_0));
            double w_1_1_0_0 = (dab_1_0 * dcd_1_0);
            gAx = (gAx + (w_1_1_0_0 * haH1_1_0__0_1_0__0_0_0__0_0_0));
            gCx = (gCx + (w_1_1_0_0 * hcH0_1_0__1_1_0__0_0_0__0_0_0));
            gAy = (gAy + (w_1_1_0_0 * (haH0_2_0__0_1_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_1_0__0_0_0__0_0_0))));
            gCy = (gCy + (w_1_1_0_0 * (hcH0_1_0__0_2_0__0_0_0__0_0_0 - (1.0 * hnH0_1_0__0_0_0__0_0_0__0_0_0))));
            gAz = (gAz + (w_1_1_0_0 * haH0_1_1__0_1_0__0_0_0__0_0_0));
            gCz = (gCz + (w_1_1_0_0 * hcH0_1_0__0_1_1__0_0_0__0_0_0));
            double w_1_2_0_0 = (dab_1_0 * dcd_2_0);
            gAx = (gAx + (w_1_2_0_0 * haH1_1_0__0_0_1__0_0_0__0_0_0));
            gCx = (gCx + (w_1_2_0_0 * hcH0_1_0__1_0_1__0_0_0__0_0_0));
            gAy = (gAy + (w_1_2_0_0 * (haH0_2_0__0_0_1__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_0_1__0_0_0__0_0_0))));
            gCy = (gCy + (w_1_2_0_0 * hcH0_1_0__0_1_1__0_0_0__0_0_0));
            gAz = (gAz + (w_1_2_0_0 * haH0_1_1__0_0_1__0_0_0__0_0_0));
            gCz = (gCz + (w_1_2_0_0 * (hcH0_1_0__0_0_2__0_0_0__0_0_0 - (1.0 * hnH0_1_0__0_0_0__0_0_0__0_0_0))));
            double w_2_0_0_0 = (dab_2_0 * dcd_0_0);
            gAx = (gAx + (w_2_0_0_0 * haH1_0_1__1_0_0__0_0_0__0_0_0));
            gCx = (gCx + (w_2_0_0_0 * (hcH0_0_1__2_0_0__0_0_0__0_0_0 - (1.0 * hnH0_0_1__0_0_0__0_0_0__0_0_0))));
            gAy = (gAy + (w_2_0_0_0 * haH0_1_1__1_0_0__0_0_0__0_0_0));
            gCy = (gCy + (w_2_0_0_0 * hcH0_0_1__1_1_0__0_0_0__0_0_0));
            gAz = (gAz + (w_2_0_0_0 * (haH0_0_2__1_0_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__1_0_0__0_0_0__0_0_0))));
            gCz = (gCz + (w_2_0_0_0 * hcH0_0_1__1_0_1__0_0_0__0_0_0));
            double w_2_1_0_0 = (dab_2_0 * dcd_1_0);
            gAx = (gAx + (w_2_1_0_0 * haH1_0_1__0_1_0__0_0_0__0_0_0));
            gCx = (gCx + (w_2_1_0_0 * hcH0_0_1__1_1_0__0_0_0__0_0_0));
            gAy = (gAy + (w_2_1_0_0 * haH0_1_1__0_1_0__0_0_0__0_0_0));
            gCy = (gCy + (w_2_1_0_0 * (hcH0_0_1__0_2_0__0_0_0__0_0_0 - (1.0 * hnH0_0_1__0_0_0__0_0_0__0_0_0))));
            gAz = (gAz + (w_2_1_0_0 * (haH0_0_2__0_1_0__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_1_0__0_0_0__0_0_0))));
            gCz = (gCz + (w_2_1_0_0 * hcH0_0_1__0_1_1__0_0_0__0_0_0));
            double w_2_2_0_0 = (dab_2_0 * dcd_2_0);
            gAx = (gAx + (w_2_2_0_0 * haH1_0_1__0_0_1__0_0_0__0_0_0));
            gCx = (gCx + (w_2_2_0_0 * hcH0_0_1__1_0_1__0_0_0__0_0_0));
            gAy = (gAy + (w_2_2_0_0 * haH0_1_1__0_0_1__0_0_0__0_0_0));
            gCy = (gCy + (w_2_2_0_0 * hcH0_0_1__0_1_1__0_0_0__0_0_0));
            gAz = (gAz + (w_2_2_0_0 * (haH0_0_2__0_0_1__0_0_0__0_0_0 - (1.0 * hmH0_0_0__0_0_1__0_0_0__0_0_0))));
            gCz = (gCz + (w_2_2_0_0 * (hcH0_0_1__0_0_2__0_0_0__0_0_0 - (1.0 * hnH0_0_1__0_0_0__0_0_0__0_0_0))));
        }
        // this thread's share of the bra's two centres, added once
        atomicAdd(&G[(bra_atom[(bra * 2 + 0)] * 3 + 0)], gAx);
        atomicAdd(&G[(bra_atom[(bra * 2 + 0)] * 3 + 1)], gAy);
        atomicAdd(&G[(bra_atom[(bra * 2 + 0)] * 3 + 2)], gAz);
        atomicAdd(&G[(bra_atom[(bra * 2 + 1)] * 3 + 0)], gCx);
        atomicAdd(&G[(bra_atom[(bra * 2 + 1)] * 3 + 1)], gCy);
        atomicAdd(&G[(bra_atom[(bra * 2 + 1)] * 3 + 2)], gCz);
    }
}
